114     function _functionCallWithValue(
115         address target,
116         bytes memory data,
117         uint256 weiValue,
118         string memory errorMessage
119     ) private returns (bytes memory) {
120         require(isContract(target), "Address: call to non-contract");
121
122         (bool success, bytes memory returndata) = target.call{ value: weiValue }(data);
123         if (success) {
124             return returndata;
125         } else {
126             if (returndata.length > 0) {
127                 assembly {
128                     let returndata_size := mload(returndata)
129                     revert(add(32, returndata), returndata_size)
130                 }
131             } else {
132                 revert(errorMessage);
133             }
134         }
135     }
